function maxBoxesInWarehouse(boxes, warehouse) {
  const limit = [...warehouse];
  for (let room = 1; room < limit.length; room++) {
    limit[room] = Math.min(limit[room], limit[room - 1]);
  }

  boxes.sort((a, b) => a - b);
  let count = 0;

  for (let room = limit.length - 1; room >= 0; room--) {
    if (count < boxes.length && boxes[count] <= limit[room]) {
      count++;
    }
  }
  return count;
}

