function maxBoxesInWarehouse(boxes, warehouse) {
  // Try every way to give each room no box or one unused box that fits through every room up to it.
  const memo = new Map();
  const best = (room, used) => {
    if (room === warehouse.length) return 0;
    const key = room * 1024 + used;
    if (memo.has(key)) return memo.get(key);
    let tightest = Infinity;
    for (let j = 0; j <= room; j++) tightest = Math.min(tightest, warehouse[j]);
    let result = best(room + 1, used);
    for (let b = 0; b < boxes.length; b++) {
      if ((used >> b) & 1) continue;
      if (boxes[b] > tightest) continue;
      result = Math.max(result, 1 + best(room + 1, used | (1 << b)));
    }
    memo.set(key, result);
    return result;
  };
  return best(0, 0);
}

