function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const top = [2, 5, 9][int(0, 2)];
    const boxes = Array.from({ length: int(1, 7) }, () => int(1, top));
    const warehouse = Array.from({ length: int(1, 7) }, () => int(1, top));
    return [boxes, warehouse];
  }
  const m = int(1500, 2000);
  const n = int(1500, 2000);
  const mode = int(0, 2);
  const boxes = Array.from({ length: m }, () => int(1, 1000000000));
  let warehouse;
  if (mode === 0) {
    warehouse = Array.from({ length: n }, () => int(1, 1000000000));
  } else {
    // A slowly falling ceiling with bumps keeps many rooms usable.
    warehouse = Array.from({ length: n }, (_, j) => Math.max(1, Math.floor(1000000000 * (1 - j / n)) - int(0, 50000000) + (mode === 2 && rand() < 0.1 ? 900000000 : 0)));
    warehouse = warehouse.map(h => Math.min(h, 1000000000));
  }
  return [boxes, warehouse];
}
